from pathlib import Path
import json,hashlib,html,datetime
O=Path(__file__).resolve().parent
rows=[json.loads(p.read_text()) for p in sorted(O.glob('policy-episode-*-s*.json'))]
controls=json.loads((O/'results-oracle30-valid.json').read_text())
cksha=hashlib.sha256((O/'best.pt').read_bytes()).hexdigest()
summary=dict(timestamp_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),checkpoint_sha256=cksha,checkpoint_epoch=15,checkpoint_step=5456,checkpoint_selection='best EMA validation noise MSE .0418417831',episodes=4,seeds=[0,1,2],completed_rollouts=len(rows),successes=sum(r['success'] for r in rows),robot_falls=sum(r['outcome']==2 for r in rows),numerical_failures=sum(r['outcome']<0 for r in rows),raised_over_4_5cm=sum(r['lift_m']>.045 for r in rows),cup_on_floor_at_end=sum(r['final_cup'][2]<.4 for r in rows),timeout_s=90,controls_30hz_successes=sum(r['success'] for r in controls),controls=controls,rollouts=rows,independent_test_session=False,initialization='Recorded first active qpos/qvel/mocap/userdata; reset native controller history, fresh control phase; task elapsed zero. No recorded future states/actions in learned rollout.',limitations=['Four validation episodes from same collection session, not new independent layouts.','Native controller history at recording start unavailable; positive control only 2/4. This is an initial-state protocol result, not a deployment success-rate estimate.','Renderer is MuJoCo training renderer, not Quest GLES.','Physics pauses while host inference runs; inference latency is measured but not applied as a live control delay.'],camera_parity=json.loads((O/'camera-parity.json').read_text()),physics_hz=1000,homie_hz=50,visual_action_hz=30,execution_steps=48,model_horizon=64,ddim_steps=10)
(O/'summary.json').write_text(json.dumps(summary,indent=2))
trs=''
for ep in sorted(set(r['episode'] for r in rows)):
 rs=[r for r in rows if r['episode']==ep];control=next(r for r in controls if r['episode']==ep)
 trs+=f'<tr><td>{ep}</td><td>{rs[0]["initial_distance_m"]*100:.1f} см</td><td>{sum(r["success"] for r in rs)} / {len(rs)}</td><td>{min(r["lift_m"] for r in rs)*100:.1f}–{max(r["lift_m"] for r in rs)*100:.1f} см</td><td>{"успех" if control["success"] else "неуспех"}</td></tr>'
page=f'''<!doctype html><html lang="ru"><meta charset="utf-8"><title>Чашка: автономный замер</title><style>body{{font:17px/1.6 system-ui;max-width:1120px;margin:40px auto;padding:24px;background:#101c25;color:#edf4f7}}section{{background:#1a2b36;border-radius:14px;padding:22px;margin:20px 0}}a{{color:#72d6bd}}video{{width:100%;border-radius:10px}}table{{border-collapse:collapse;width:100%;font-size:15px}}th,td{{text-align:left;border-bottom:1px solid #456;padding:10px}}code{{overflow-wrap:anywhere}}h1{{line-height:1.2}}</style>
<h1>Чашка: первый автономный замер</h1><p>15 октября 2026 · лучший checkpoint обычной чашки · MuJoCo + HOMIE</p>
<section><strong>{summary['successes']} успешных переносов из {len(rows)} попыток.</strong><p>Четыре validation-старта × три seed генерации действий, до 90 секунд симуляции на попытку. Падений робота: {summary['robot_falls']}; численных ошибок: {summary['numerical_failures']}. Политика касается чашки, но пока не выполняет устойчивый захват и перенос.</p><p><b>Ограничение:</b> контроль с записанными командами даёт только {summary['controls_30hz_successes']}/4 успеха. Поэтому этот замер нельзя выдавать за окончательный процент успешности в шлеме. На двух стартах, где контроль проходит, обученная политика также не справляется.</p></section>
<video controls preload="metadata" poster="comparison-preview.jpg" src="cup-control-vs-policy.mp4"></video><p>Слева — физический прогон сохранённых команд, справа — самостоятельные действия обученной политики. Один и тот же старт, модель, HOMIE и критерий успеха. Показаны первые 15 секунд; успешный левый прогон заканчивается раньше и затем удерживается последний кадр. Это визуализация рассчитанной симуляции, не экранная запись Quest.</p>
<section><h2>Результаты</h2><table><tr><th>Эпизод</th><th>Перенос</th><th>Политика</th><th>Максимальный подъём</th><th>Записанные команды, 30 Гц</th></tr>{trs}</table><p>Всего подъём выше 4.5 см: {summary['raised_over_4_5cm']} / {len(rows)}. Сам по себе подъём не считается успехом. В конце чашка на полу: {summary['cup_on_floor_at_end']} / {len(rows)}.</p></section>
<section><h2>Как измерялось</h2><p>Использован EMA best.pt: эпоха 15, шаг 5456; все 301 эпоха обучения завершились. Выбранный checkpoint имеет минимальную validation denoising MSE, а не подтверждённый task success. SHA256 сверён с MIPT: <code>{cksha}</code>.</p><p>Архивный MuJoCo 3.3.7 MJB и сохранённые ONNX HOMIE проверяются по исходному manifest. Физика 1000 Гц, HOMIE 50 Гц; RGB и команды 30 Гц. Политика видит две последние RGB-картинки и две предыдущие команды; DDIM 10 шагов, предсказание 64, исполнение 48. После начала попытки записанные действия, состояния и положение чашки не передаются политике.</p><p>Начальные RGB совпадают с обучающим HDF5: три сцены побайтно, в четвёртой отличается один цветовой канал одного пикселя на 1/255. Камера использует текущую физическую голову и предыдущий предсказанный gaze; тени отключены.</p><p>Восстанавливаются начальные qpos/qvel, цель и task userdata. Скрытая история HOMIE в записях отсутствует и начинается с нуля. Данные содержат промежуток между снимком калибровки и первым активным кадром, в котором нет полного потока команд; точное динамическое восстановление этого промежутка не подтверждено. Записанные команды на 100 Гц также дают 2/4 успеха в контрольных прогонах до 30 секунд.</p><p>Это четыре сцены из той же сессии, а не независимая проверка новых расстановок. Рендер MuJoCo отличается от Quest GLES. Во время вычисления действий физическое время приостановлено: реальная задержка вывода на шлеме этим тестом не моделируется.</p></section>
<p><a href="summary.json">Все метрики и ограничения</a> · <a href="evaluate.py">Код замера</a> · <a href="camera-parity.json">Проверка RGB</a> · <a href="../dexweave-cup-box-20261015/REPORT.html">Четыре параллельных обучения DexWeave</a></p></html>'''
(O/'REPORT.html').write_text(page)
print(json.dumps({k:summary[k] for k in ('completed_rollouts','successes','robot_falls','numerical_failures','raised_over_4_5cm','cup_on_floor_at_end','controls_30hz_successes')},indent=2))
